public abstract class AEBaseInvBlockEntity extends AEBaseBlockEntity implements InternalInventoryHost {

    public AEBaseInvBlockEntity(BlockEntityType<?> blockEntityType, BlockPos pos, BlockState blockState) {
        super(blockEntityType, pos, blockState);
    }

    @Override
    public void loadTag(ValueInput data) {
        super.loadTag(data);
        var inv = this.getInternalInventory();
        if (inv != InternalInventory.empty()) {
            var opt = data.child("inv").orElse(null);
            for (int x = 0; x < inv.size(); x++) {
                ItemStack item = ItemStack.EMPTY;
                if (opt != null) {
                    item = opt.read("item" + x, ItemStack.OPTIONAL_CODEC).orElse(ItemStack.EMPTY);
                }
                inv.setItemDirect(x, item);
            }
        }
    }

    public abstract InternalInventory getInternalInventory();

    @Override
    public void saveAdditional(ValueOutput data) {
        super.saveAdditional(data);
        var inv = this.getInternalInventory();
        if (inv != InternalInventory.empty()) {
            var opt = data.child("inv");
            for (int x = 0; x < inv.size(); x++) {
                var is = inv.getStackInSlot(x);
                if (!is.isEmpty()) {
                    opt.store("item" + x, ItemStack.OPTIONAL_CODEC, is);
                }
            }
        }
    }

    @Override
    public void addAdditionalDrops(Level level, BlockPos pos, List<ItemStack> drops) {
        var inv = getInternalInventory();
        for (var stack : inv) {
            var genericStack = GenericStack.unwrapItemStack(stack);
            if (genericStack != null) {
                genericStack.what().addDrops(
                        genericStack.amount(),
                        drops,
                        level,
                        pos);
            } else {
                drops.add(stack);
            }
        }
    }

    @Override
    public void clearContent() {
        super.clearContent();
        getInternalInventory().clear();
    }

    @Override
    public void saveChangedInventory(AppEngInternalInventory inv) {
        this.saveChanges();
    }

    protected InternalInventory getExposedInventoryForSide(Direction side) {
        return this.getInternalInventory();
    }

    @Nullable

protected Item getItemFromBlockEntity() {
    return REPRESENTATIVE_ITEMS.getOrDefault(getType(), Items.AIR);
}

@Override
protected void loadAdditional(ValueInput input) {
    // On the client, this can either be data received as part of an initial chunk update,
    // or as part of a sole block entity data update.
    RegistryAccess registryAccess = null;
    if (input.lookup() instanceof RegistryAccess) {
        registryAccess = (RegistryAccess) input.lookup();
    } else if (level != null) {
        registryAccess = level.registryAccess();
    }
    var updateData = input.getString("#upd").orElse(null);
    if (updateData != null) {
        var decodedUpdateData = Base64.getDecoder().decode(updateData);

        if (registryAccess == null) {
            LOG.warn("Ignoring  update packet for {} since no registry is available.", this);
        } else if (readUpdateData(
                new RegistryFriendlyByteBuf(Unpooled.wrappedBuffer(decodedUpdateData), registryAccess,
                        ConnectionType.NEOFORGE))) {
            // Triggers a chunk re-render if the level is already loaded
            if (level != null) {
                requestModelDataUpdate();
                level.sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(), 0);
            }
        }
        return;
    }

    // Load visual client-side data (used by PonderJS)
    input.child("visual").ifPresent(this::loadVisualState);

    super.loadAdditional(input);
    loadTag(input);
}

